// Format: blank lines and lines starting with `#` are ignored; every other
// line is `key=value`, split on the first `=` so values may contain one.
function parseConfig(text) {
  // Null prototype so a key named `__proto__` or `constructor` stays config
  // data instead of reaching Object.prototype. Defensive hygiene for a
  // hand-rolled parser, not a response to a known untrusted source.
  const config = Object.create(null);
  const lines = text.split('\n');
  for (let i = 0; i < lines.length; i++) {
    const trimmed = lines[i].trim();
    if (trimmed === '' || trimmed.startsWith('#')) continue;
    const eq = trimmed.indexOf('=');
    // Reject rather than guess: with no `=`, slice(0, -1) would silently drop
    // the last character and store a plausible-looking but wrong key.
    if (eq <= 0) {
      throw new Error(`Malformed config line ${i + 1}: ${trimmed}`);
    }
    config[trimmed.slice(0, eq).trim()] = trimmed.slice(eq + 1).trim();
  }
  return config;
}

